{"returncode":0,"stdout":"#'   name, or a one-sided formula evaluated in [fixest::fixest_data()].
#' @param small_sample For clustered covariance, apply the conventional
#'   `G/(G-1) * (n-1)/(n-K)` CR1 correction.  Set to `FALSE` for CR0.
#' @param verify Passed to [iv_design()] when `fit` is a `fixest` model.
#' @param tolerance Passed to [iv_design()].
#'
#' @return A named covariance matrix compatible with `summary.fixest(vcov = )`.
#' @export
vcov_iv <- function(fit, type = "HC1", cluster = NULL,
                    small_sample = TRUE, verify = TRUE,
                    tolerance = 1e-7) {
  .check_scalar_logical(small_sample, "small_sample")
  .check_scalar_logical(verify, "verify")
  type <- toupper(.check_scalar_character(type, "type"))
  allowed <- c("HC1", "HC0", "IID", "CLUSTER")
  if (!type %in% allowed) {
    stop(
      "`type` must be one of ", paste(allowed, collapse = ", "), ".",
      call. = FALSE
    )
  }

  original_fit <- if (inherits(fit, "fixest")) fit else NULL
  design <- if (inherits(fit, "ccv_iv_design")) {
    fit
  } else {
    iv_design(fit, verify = verify, tolerance = tolerance)
  }

  n <- design$nobs
  K <- design$ncoef
  if (n <= K) {
    stop("The covariance requires more observations than coefficients.",
         call. = FALSE)
  }

  if (type == "IID") {
    sigma2 <- sum(design$residuals^2) / (n - K)
    covariance <- sigma2 * design$bread
    covariance_label <- "CCV IV iid"
  } else {
    scores <- sweep(design$Xhat, 1L, design$residuals, `*`)
    if (type == "CLUSTER") {
      groups <- .resolve_cluster(cluster, original_fit, n)
      G <- nlevels(groups)
      if (G < 2L) {
        stop("Cluster covariance requires at least two clusters.", call. = FALSE)
      }
      cluster_scores <- rowsum(scores, groups, reorder = FALSE)
      meat <- crossprod(cluster_scores)
      correction <- if (small_sample) {
        (G / (G - 1)) * ((n - 1) / (n - K))
      } else {
        1
      }
      meat <- correction * meat
      covariance_label <- if (small_sample) "CCV IV cluster (CR1)" else
        "CCV IV cluster (CR0)"
    } else {
      meat <- crossprod(scores)
      if (type == "HC1") {
        meat <- (n / (n - K)) * meat
      }
      covariance_label <- paste("CCV IV", type)
    }
    covariance <- design$bread %*% meat %*% t(design$bread)
  }

  covariance <- (covariance + t(covariance)) / 2
  dimnames(covariance) <- list(design$coefficient_names,
                               design$coefficient_names)
  attr(covariance, "type") <- covariance_label
  covariance
}

#' Standard errors from a fixest IV sandwich
#'
#' @inheritParams vcov_iv
#' @return A named numeric vector of standard errors.
#' @export
iv_se <- function(fit, type = "HC1", cluster = NULL,
                  small_sample = TRUE, verify = TRUE,
                  tolerance = 1e-7) {
  covariance <- vcov_iv(
    fit = fit,
    type = type,
    cluster = cluster,
    small_sample = small_sample,
    verify = verify,
    tolerance = tolerance
  )
  variances <- diag(covariance)
  if (any(variances < -sqrt(.Machine$double.eps))) {
    warning("The covariance matrix has a negative diagonal entry.",
            call. = FALSE)
  }
  result <- sqrt(pmax(variances, 0))
  names(result) <- rownames(covariance)
  result
}

.check_fixest_iv <- function(fit) {
  if (!inherits(fit, "fixest") || inherits(fit, "fixest_multi")) {
    stop("`fit` must be a single fixest model.", call. = FALSE)
  }
  iv_formula <- tryCatch(
    stats::formula(fit, type = "iv"),
    error = function(error) NULL
  )
  if (is.null(iv_formula)) {
    stop("`fit` must be an instrumental-variables fixest model.", call. = FALSE)
  }
  model_weights <- tryCatch(stats::weights(fit), error = function(error) NULL)
  if (!is.null(model_weights) && length(model_weights)) {
    stop("Weighted fixest IV models are not currently supported.", call. = FALSE)
  }
  invisible(TRUE)
}

.fixest_matrix <- function(fit, type) {
  value <- tryCatch(
    stats::model.matrix(fit, type = type, as.matrix = TRUE,
                        collin.rm = TRUE),
    error = function(error) {
      stop(
        "Could not extract fixest model matrix `", type, "`: ",
        conditionMessage(error),
        call. = FALSE
      )
    }
  )
  if (is.null(dim(value))) {
    value <- matrix(value, ncol = 1L)
  }
  storage.mode(value) <- "double"
  if (is.null(colnames(value))) {
    colnames(value) <- type
  }
  value
}

.resolve_cluster <- function(cluster, fit, n) {
  if (is.null(cluster)) {
    stop("`cluster` is required when `type = \"cluster\"`.", call. = FALSE)
  }
  if (inherits(cluster, "formula")) {
    if (is.null(fit)) {
      stop("A cluster formula requires the original fixest model.",
           call. = FALSE)
    }
    data <- fixest::fixest_data(fit, sample = "estimation")
    frame <- stats::model.frame(cluster, data = data,
                                na.action = stats::na.pass)
    if (ncol(frame) != 1L) {
      stop("Only one-way cluster formulas are supported.", call. = FALSE)
    }
    cluster <- frame[[1L]]
  } else if (is.character(cluster) && length(cluster) == 1L) {
    if (is.null(fit)) {
      stop("A cluster column name requires the original fixest model.",
           call. = FALSE)
    }
    data <- fixest::fixest_data(fit, sample = "estimation")
    if (!cluster %in% names(data)) {
      stop("Cluster column `", cluster, "` was not found.", call. = FALSE)
    }
    cluster <- data[[cluster]]
  }
  if (!is.atomic(cluster) || is.matrix(cluster) || length(cluster) != n) {
    stop("`cluster` must identify one cluster for each estimation observation.",
         call. = FALSE)
  }
  if (anyNA(cluster)) {
    stop("`cluster` cannot contain missing values.", call. = FALSE)
  }
  droplevels(factor(cluster))
}

.check_scalar_logical <- function(value, name) {
  if (!is.logical(value) || length(value) != 1L || is.na(value)) {
    stop("`", name, "` must be TRUE or FALSE.", call. = FALSE)
  }
  invisible(value)
}

.check_scalar_character <- function(value, name) {
  if (!is.character(value) || length(value) != 1L || is.na(value) ||
      !nzchar(value)) {
    stop("`", name, "` must be a nonempty character scalar.", call. = FALSE)
  }
  value
}

.check_positive_number <- function(value, name) {
  if (!is.numeric(value) || length(value) != 1L || !is.finite(value) ||
      value <= 0) {
    stop("`", name, "` must be a positive finite number.", call. = FALSE)
  }
  invisible(value)
}

.check_positive_integer <- function(value, name) {
  if (!is.numeric(value) || length(value) != 1L || is.na(value) ||
      value < 1 || value != as.integer(value)) {
    stop("`", name, "` must be a positive integer.", call. = FALSE)
  }
  invisible(value)
}

