real scalar FE(vector Y, vector W, vector Cluster) {
    //A = (Y, W)
    //Acoll = _mm_collapse2(A, 1, Cluster)
    //y = Y - Acoll[,1]
    Wmean = _mm_collapse2(W, 1, Cluster)
    w = W - Wmean
    tau_fe = sum(Y:*w)/sum(W:*w)
    return(tau_fe)
}
end

