"""Optimised FWL engine.

Three changes against the first implementation, in descending order of payoff:

1. Group means via `np.add.reduceat` on a group-sorted permutation, computed for ALL columns in
   one vectorised call, instead of one `np.bincount` per column. The per-sweep cost stops scaling
   with the number of columns the way a Python loop over columns does.
2. Many treatment vectors demeaned in a single alternating-projections run, so the convergence
   sweeps are shared rather than repeated per specification.
3. Residualised outcomes cached per (fixed-effect set, sample mask), since the outcome is
   demeaned identically for every specification that shares those two.
"""

import numpy as np


class FEProjector:
    """Alternating projections against a fixed set of integer-coded fixed effects."""

    def __init__(self, fes: list[np.ndarray]):
        self.fes = []
        for f in fes:
            order = np.argsort(f, kind="stable")
            sorted_f = f[order]
            starts = np.flatnonzero(np.r_[True, sorted_f[1:] != sorted_f[:-1]])
            counts = np.diff(np.r_[starts, sorted_f.size]).astype(np.float64)
            self.fes.append((order, starts, counts, sorted_f[starts]))
        self.n = fes[0].size if fes else 0

    def _sweep(self, X: np.ndarray) -> float:
        worst = 0.0
        for order, starts, counts, _ in self.fes:
            sums = np.add.reduceat(X[order], starts, axis=0)
            means = sums / counts[:, None]
            adj = np.repeat(means, counts.astype(np.int64), axis=0)
            X[order] -= adj
            m = float(np.abs(adj).max()) if adj.size else 0.0
            worst = max(worst, m)
        return worst

    def demean(self, X: np.ndarray, tol: float = 1e-10, maxit: int = 2000) -> np.ndarray:
        X = np.array(X, dtype=np.float64, copy=True)
        if X.ndim == 1:
            X = X[:, None]
        if not self.fes:
            return X - X.mean(axis=0, keepdims=True)
        scale = max(float(np.abs(X).max()), 1e-12)
        for _ in range(maxit):
            if self._sweep(X) < tol * scale:
                break
        return X

    @property
    def n_params(self) -> int:
        return sum(len(s) for _, s, _, _ in self.fes) - (len(self.fes) - 1)


class ResidualCache:
    """Caches demeaned outcomes and projectors keyed by (fe set, sample mask)."""

    def __init__(self):
        self._proj = {}
        self._y = {}

    def projector(self, key, fes_factory) -> FEProjector:
        if key not in self._proj:
            self._proj[key] = FEProjector(fes_factory())
        return self._proj[key]

    def outcome(self, key, proj: FEProjector, y: np.ndarray) -> np.ndarray:
        if key not in self._y:
            self._y[key] = proj.demean(y)[:, 0]
        return self._y[key]

    def clear(self):
        self._proj.clear()
        self._y.clear()


def ols_scalar(yt: np.ndarray, dt: np.ndarray):
    """beta, residuals, S for an already-residualised scalar regressor."""
    S = float(dt @ dt)
    if S <= 0 or not np.isfinite(S):
        return np.nan, np.full_like(yt, np.nan), S
    beta = float(dt @ yt) / S
    return beta, yt - beta * dt, S


def ols_multi(yt: np.ndarray, Dt: np.ndarray):
    """beta vector, residuals, bread (D'D)^-1 for an already-residualised regressor matrix."""
    G = Dt.T @ Dt
    try:
        bread = np.linalg.inv(G)
    except np.linalg.LinAlgError:
        bread = np.linalg.pinv(G)
    beta = bread @ (Dt.T @ yt)
    return beta, yt - Dt @ beta, bread

